package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import java.util.regex.*;import org.json.*;
/** Prepared existing Java class can be rewritten and really compiled/loaded on device. */
final class JavaLive{
 static volatile float gap=0;static volatile Class<?> active;static int loadedRevision=-1;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-live-java",0);}
 static synchronized void restore(Context c){int rev=prefs(c).getInt("revision",0);if(loadedRevision==rev)return;try{String path=prefs(c).getString("jar","");active=path.isEmpty()?null:OnDeviceJava.load(c,new File(path));if(active!=null)test(active);gap=active==null?0:((Number)active.getMethod("kissGap").invoke(null)).floatValue();loadedRevision=rev;}catch(Throwable broken){active=null;gap=0;loadedRevision=rev;prefs(c).edit().putString("error","No pude cargar la clase activa; usé la base: "+broken).apply();}}
 static void test(Class<?> type)throws Exception{JavaPatchPolicy.sequence((String)type.getMethod("celebration").invoke(null));float x=((Number)type.getMethod("kissGap").invoke(null)).floatValue();if(Float.isNaN(x)||Float.isInfinite(x)||x<0||x>4)throw new IllegalArgumentException("kissGap fuera de límites");String q="pedido sin cambios";if(!q.equals(type.getMethod("rewrite",String.class).invoke(null,q)))throw new IllegalArgumentException("rewrite alteró una entrada de control");}
 static String source(Context c){return prefs(c).getString("source",JavaPatchPolicy.BASE);}
 static synchronized void stage(Context c,String source,int revision)throws Exception{if(prefs(c).getInt("revision",0)!=revision)throw new IllegalArgumentException("La versión Java cambió mientras editabas.");if(source.length()>12000)throw new IllegalArgumentException("Fuente demasiado larga");if(!prefs(c).edit().putString("draft",source).putInt("base",revision).commit())throw new IOException("No pude guardar la fuente Java");}
 static String activate(Context c)throws Exception{String source=prefs(c).getString("draft","");int base=prefs(c).getInt("base",-1);if(source.isEmpty())return "Primero guardá un borrador Java.";JavaPatchPolicy.validate(source);OnDeviceJava.Build built=OnDeviceJava.compile(c,source);test(built.type);synchronized(JavaLive.class){if(prefs(c).getInt("revision",0)!=base||!prefs(c).getString("draft","").equals(source))throw new IllegalArgumentException("La fuente o la versión cambió durante la compilación; no activé el resultado.");JSONObject backup=new JSONObject().put("source",source(c)).put("jar",prefs(c).getString("jar","")).put("revision",base);if(!prefs(c).edit().putString("backup",backup.toString()).putString("source",source).putString("jar",built.jar.getAbsolutePath()).putInt("revision",base+1).putLong("changedAt",System.currentTimeMillis()).putString("log",built.log).remove("error").remove("draft").commit())throw new IOException("No pude activar la clase");active=built.type;gap=((Number)active.getMethod("kissGap").invoke(null)).floatValue();loadedRevision=base+1;}return "Java revisión "+(base+1)+" compilada y activada en Android.\n"+built.log;}
 static synchronized String rollback(Context c)throws Exception{String raw=prefs(c).getString("backup","");if(raw.isEmpty())return "No hay una versión Java anterior.";JSONObject b=new JSONObject(raw);String jar=b.optString("jar");Class<?> type=jar.isEmpty()?null:OnDeviceJava.load(c,new File(jar));if(type!=null)test(type);if(!prefs(c).edit().putString("source",b.getString("source")).putString("jar",jar).putInt("revision",prefs(c).getInt("revision",0)+1).putLong("changedAt",System.currentTimeMillis()).remove("backup").remove("error").remove("draft").commit())throw new IOException("No pude recuperar Java");loadedRevision=-1;restore(c);return "Recuperé la clase Java anterior. Los próximos pedidos usan esa versión.";}
 static String rewrite(Context c,String message){restore(c);if(active==null)return message;try{String normalized=ChatLanguage.normalize(message);String changed=(String)active.getMethod("rewrite",String.class).invoke(null,normalized);return changed.equals(normalized)?message:changed;}catch(Exception e){return message;}}
 static String patched(String original,String change)throws Exception{String q=ChatLanguage.normalize(change);if(q.startsWith("celebracion ")){String value=change.trim().substring("celebracion ".length()).replace(" ","");JavaPatchPolicy.sequence(value);String next=original.replaceFirst("public\\s+static\\s+String\\s+celebration\\(\\)\\s*\\{\\s*return\\s*\"[^\"]*\";\\s*\\}",java.util.regex.Matcher.quoteReplacement("public static String celebration() { return \""+value+"\"; }"));if(next.equals(original)&&!original.contains("\""+value+"\""))throw new IllegalArgumentException("No identifiqué el método celebration.");JavaPatchPolicy.validate(next);return next;}
 if(q.startsWith("separacion del beso ")){String value=change.trim().substring("separacion del beso ".length()).replace(',','.');float gap=Float.parseFloat(value);if(Float.isNaN(gap)||Float.isInfinite(gap)||gap<0||gap>4)throw new IllegalArgumentException("La separación debe estar entre0 y4.");String next=original.replaceFirst("public\\s+static\\s+float\\s+kissGap\\(\\)\\s*\\{[^}]*\\}",java.util.regex.Matcher.quoteReplacement("public static float kissGap() { return "+gap+"f; }"));JavaPatchPolicy.validate(next);return next;}throw new IllegalArgumentException("Puedo reescribir celebration o separacion del beso; otros cambios necesitan edición y validación explícita.");}
 static BananaEngine.Result handle(Context c,String message)throws Exception{String q=ChatLanguage.normalize(message);if(q.startsWith("corrige java ")){int colon=message.indexOf(':');String change=colon>=0?message.substring(colon+1).trim():message.substring("corrige java ".length());try{stage(c,patched(source(c),change),prefs(c).getInt("revision",0));return MobileCore.say(c,activate(c),"java");}catch(Throwable failure){prefs(c).edit().putString("error",failure.toString()).apply();return MobileCore.say(c,"No cambié la clase activa: "+failure,"java");}}if(q.equals("estado java"))return MobileCore.say(c,"Java local · revisión "+prefs(c).getInt("revision",0)+"\nFuente: BananaBehavior.java\nAlcance: una clase preparada, métodos celebration, kissGap y rewrite. Compilación real ECJ + DX y carga DEX. No reemplaza todo el APK.\n"+prefs(c).getString("log","")+"\n"+prefs(c).getString("error",""),"java");if(q.equals("ver java"))return MobileCore.say(c,source(c),"java");if(q.equals("prepara prueba java")){stage(c,JavaPatchPolicy.BASE.replace("baila,saluda,salta","salta,saluda,baila"),prefs(c).getInt("revision",0));return MobileCore.say(c,"Modifiqué el método celebration de BananaBehavior.java en el borrador. Decí ‘compila y activa java’.","java");}if(q.equals("compila y activa java")){try{return MobileCore.say(c,activate(c),"java");}catch(Throwable failure){String text="No activé Java: "+failure; prefs(c).edit().putString("error",text).apply();return MobileCore.say(c,text,"java");}}if(q.equals("revierte java"))return MobileCore.say(c,rollback(c),"java");if(q.equals("busca este error java")){String error=prefs(c).getString("error","");return MobileCore.say(c,ResearchConversation.reply(c,"busca documentacion ECJ DX compilacion Java Android "+error.replaceAll("/[^ ]+","archivo").substring(0,Math.min(160,error.replaceAll("/[^ ]+","archivo").length())),""),"fuentes");}
 Matcher m=Pattern.compile("^(.+?) celebra en java$").matcher(q);if(!m.matches())return null;restore(c);SceneDraft base=MobileCore.scene(c);if(base==null)return MobileCore.say(c,"Primero creá un personaje.","java");SceneDraft.Actor actor=RuntimeProgram.resolve(base,m.group(1));if(actor==null)return MobileCore.say(c,"Nombrá un personaje existente para ejecutar celebration.","java");String recipe=ProjectRuntime.recipe(active==null?ActionProfile.celebration():(String)active.getMethod("celebration").invoke(null));SceneDraft scene=base.copy();int slot=scene.actions.isEmpty()?0:ObjectTransfer.beats(scene);for(String op:JavaPatchPolicy.sequence(recipe)){if(slot>=SceneTiming.MAX_BEATS)return MobileCore.say(c,"No queda tiempo en la toma.","java");SceneDirector.step(scene,scene.get(actor.name),op,slot++,"","");}SceneTiming.fit(scene);SceneConsistency.require(scene);CreatorSession owner=CreatorMemory.load(c);CreatorSession.Result result=owner.update(scene,owner.pending!=null,"Ejecuté celebration desde la clase Java: "+recipe,false);CreatorMemory.save(c,owner,result.commit);BananaEngine.Result out=MobileCore.say(c,result.text,"java");out.changed=result.commit!=null;if(out.draft)out.mode="borrador";return out;}
}
